    @pytest.mark.parametrize("late_at", ["s.set", "s.get"])
    def test_l1_checks_deadline_after_last_return(monkeypatch, late_at):
        clock = [0.0]
        calls = []
        case = {**CASE, "timeout_seconds": 1}
        if late_at == "s.set":
            case["postconditions"] = []

        class Channel:
